def solve(s: str) -> bool:
    """Return True if brackets in the string are balanced.
    Handles parentheses (), square brackets [], and curly braces {}.
    Ignores all other characters.
    """
    stack = []
    opening = set('([{')
    matches = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matches:
