def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def is_land(val):
        return val == 1 or val == '1'
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or not is_land(grid[i][j]):
                continue
            visited[i][j] = True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if is_land(grid[i][j]) and not visited[i][j]:
                dfs(i,j)
                count += 1
    return count

